@cache
def _arxiv_index():
    "Disk cache for arXiv metadata, opened on first use rather than at import."
    from diskcache import Index
    return Index(str(fossick_cache('arxiv_cache.db')))

def _fetch_arxiv_meta(arxiv_id:str, **kw):
    "Fetch and parse arxiv metadata for a given ID; result is cached to disk"
    r = http_get(f'https://export.arxiv.org/api/query?id_list={arxiv_id}', **kw)
    if r.status != 200: raise Exception(f"Failed to fetch arxiv data: {r.status}")
    ns = {'a': 'http://www.w3.org/2005/Atom'}
    entry = etree.fromstring(r.body).find('a:entry', ns)
    if entry is None: raise Exception("No paper found")
    def txt(tag): return entry.find(f'a:{tag}', ns).text
    pu = first(L(entry.findall('a:link',ns)).filter(lambda l: l.get('title')=='pdf').map(lambda l: l.get('href')))
    au = L(entry.findall('a:author', ns)).map(lambda a: a.find('a:name', ns).text)
    return dict(title=txt('title').strip(), summary=txt('summary').strip(),
                published=txt('published'), link=txt('id'), pdf_url=pu, authors=list(au))

# %% ../nbs/00_core.ipynb #d2ed0fcb31d735a8
def _arxiv_key(url:str) -> tuple:
    "Split an arXiv URL/ID into its bare id and version suffix, e.g. '1706.03762', 'v7'."
    aid = url.rsplit('/', 1)[-1]
    ver = re.search(r'v(\d+)$', aid)
    return re.sub(r'v\d+$', '', aid), (f'v{ver.group(1)}' if ver else '')

def read_arxiv(url:str, # arxiv PDF URL, or arxiv abstract URL, or arxiv ID
               save_pdf:bool=True, # if True, saves the downloaded PDF to disk
               save_dir:str='.', # directory in which to save the PDF
               source:bool=False, # if True, also extract the paper's full text into `source`
               force:bool=False, # if True, forces re-download even if cached
               **kw # http_get kwargs (e.g. verify=False to skip SSL verification, headers=... etc.)
               )-> dict:
    """Paper metadata from an arXiv URL or ID: `title, authors, summary, published, link, pdf_url,
    pdf_path` and, with `source=True`, the full text in `source`. The live `PdfDocument` comes back
    under `doc` when this call downloaded one.

    Only JSON-able fields are cached — a `PdfDocument` is a live handle, not cache content."""
    arxiv_id, ver_sfx = _arxiv_key(url)
    key, idx = f'{arxiv_id}{ver_sfx}', _arxiv_index()
    if force: idx.pop(key, None)
    res = dict(idx[key]) if key in idx else None
    pdf_path = Path(save_dir)/f'{key}.pdf' if save_pdf else None
    if res is None:
        res = dict(_fetch_arxiv_meta(arxiv_id, **kw))   # kw belongs to the request, not the result
        if not res['pdf_url']: raise Exception("No PDF URL found in arxiv metadata")
        res['pdf_path'] = None
    have = bool(res.get('pdf_path')) and Path(res['pdf_path']).exists()
    doc, want_src = None, source and not res.get('source')
    if (save_pdf and not have) or want_src:
        doc = get_pdf(res['pdf_url'], save_path=pdf_path, **kw)
        if doc is None: raise Exception(f"Could not download the PDF for {key} from {res['pdf_url']}")
        if pdf_path: res['pdf_path'] = str(pdf_path)
    if want_src: res['source'] = pdf2md(doc, out_path=Path(save_dir)/f'{key}.ipynb')
    idx[key] = res
    return dict(res, doc=doc)

